import sys


def main():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    a = [int(x) for x in data[1 : n + 1]]
    a.sort()

    ans = 0
    for k in range(n - 1, 1, -1):
        target = a[k]
        i = 0
        j = k - 1
        while i < j:
            if a[i] + a[j] > target:
                ans += j - i
                j -= 1
            else:
                i += 1

    print(ans)


if __name__ == "__main__":
    main()
